/** Helper : résout un voicegroup par nom (avec ou sans préfixe `voicegroup_`). */
export function lookupVoicegroup(name: string): VoiceGroup | null {
  return VOICEGROUPS_BY_NAME[name] ?? VOICEGROUPS_BY_NAME[name.replace(/^voicegroup_/, '')] ?? null;
}
